        PrintWriter writer = new PrintWriter(System.out);
        new TaskC().process(reader, writer);
        writer.close();
    }

    static class TaskC {
        public static boolean isAngleLessThan90Degrees(Point p1, Point p2) {
            double mag1 = p1.getMagnitude();
            double mag2 = p2.getMagnitude();
