import math
import sys

class Point:
    def __init__(self, a, b, c, d, e):
        self.v = a
        self.w = b
        self.x = c
        self.y = d
        self.z = e

    def get_magnitude(self):
        return math.sqrt(self.v * self.v + self.w * self.w + self.x * self.x + self.y * self.y + self.z * self.z)

def is_angle_less_than_90_degrees(p1, p2):
    mag1 = p1.get_magnitude()
    mag2 = p2.get_magnitude()
    dot = p1.v * p2.v + p1.w * p2.w + p1.x * p2.x + p1.y * p2.y + p1.z * p2.z
    # To prevent floating point errors, clip the value within [-1, 1]
    cos_angle = max(-1.0, min(1.0, dot / (mag1 * mag2))) if mag1 != 0 and mag2 != 0 else 1
    angle = math.degrees(math.acos(cos_angle))
    return angle < 90

def main():
    input_lines = sys.stdin.read().splitlines()
    n = int(input_lines[0])
    if n > 11:
        print(0)
        return
    points = []
    for i in range(1, n + 1):
        parts = list(map(int, input_lines[i].split()))
        points.append(Point(*parts))
    valid_indices = set()
    for i in range(n):
        is_valid = True
        for j in range(n):
            for k in range(n):
                if i != j and i != k and j != k:
                    p1 = points[j]
                    p2 = points[k]
                    p3 = points[i]
                    v1 = Point(p1.v - p3.v, p1.w - p3.w, p1.x - p3.x, p1.y - p3.y, p1.z - p3.z)
                    v2 = Point(p2.v - p3.v, p2.w - p3.w, p2.x - p3.x, p2.y - p3.y, p2.z - p3.z)
                    if is_angle_less_than_90_degrees(v1, v2):
                        is_valid = False
        if is_valid:
            valid_indices.add(i + 1)
    if not valid_indices:
        print(0)
    else:
        print(len(valid_indices))
        for idx in sorted(valid_indices):
            print(idx)

